def filter_by_tag(self, tag: str) -> list[Task]:
    return [t for t in self._tasks.values() if tag in t.tags]

def archive_completed_tasks(self) -> list[Task]:
    """Remove all completed tasks from the manager and return them."""
    archived = [task for task in self._tasks.values() if task.completed]
    for task in archived:
        del self._tasks[task.id]
    return archived
